# Launch packages that cover more than their main destination, by page slug -> extra destination slugs.
# Only pages with no extra places yet are filled, so anything set in admin is kept.
LAUNCH_PACKAGE_STOPS = {
    'vizag-and-araku-3-days-tour-package': ('vizag',),
    'araku-lambasingi-tour-package': ('araku-valley',),
    'vizag-araku-lambasingi-4-5-days-tour-package': ('vizag', 'lambasingi'),
}


def fill_launch_package_stops(apps, schema_editor):
    ContentPage = apps.get_model('core', 'ContentPage')
    Destination = apps.get_model('core', 'Destination')
    for slug, stops in LAUNCH_PACKAGE_STOPS.items():
        page = ContentPage.objects.filter(slug=slug, page_type='package').first()
        if page is None or page.also_visits.exists():
            continue
        page.also_visits.set(Destination.objects.filter(slug__in=stops))


